#!/usr/bin/env python3
"""Apply dated original screening decisions to retrieved public metadata.
Run after the three retrieval scripts. No source text or person-level data retained.
"""
import datetime as dt,json,pathlib
root=pathlib.Path(__file__).resolve().parent
def load(n):return json.loads((root/n).read_text())
def write(n,d):(root/n).write_text(json.dumps(d,indent=2)+'\n')
def jsonl(n,rows):(root/n).write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in rows))
r=load('search-log.json');old=load('baseline/updates__2026-10-17__search-log.json');supp=load('supplement-selected-metadata.json')
decisions={
 '39947542':'Already encountered historical preclinical paper. Explicitly retracted; exclude from positive mechanism/efficacy evidence. Linked notice unchanged. Publication February 2025, not a new October study.',
 '40229987':'Already screened 2025 occlusal-device case reports; metadata revision does not create new evidence. No individual case details reviewed or retained today.',
 '42527169':'Already encountered historical retraction notice; electronic July 29, 2026 with October issue assignment. Linked retraction/erratum fields unchanged. Not a new October retraction.',
 '42808868':'Already screened secondary adult OCD review; electronic/issue October 16 but database entry September 29. Excluded from primary evidence.',
 '42867549':'Duplicate pediatric cross-sectional allergy study already in main evidence ledger; first publication October 13. Revision October 16 is not a new study or adult applicability.',
 '42888480':'Newly encountered pediatric narrative review, electronic October 16 and PubMed entry October 17. Abstract assessed as secondary synthesis; exclude from primary-study evidence and do not treat proposed diagnostic framework as validated clinical accuracy.'}
for x in r['pubmed']['date_type_correction_screen']:x['screening_decision']=decisions[x['pmid']]
for x in r['registry_records']:
 if x['nctId']=='NCT05158439':x['outcome_summary']='Withdrawn protocol, actual enrollment zero, no results; feasibility/status evidence only.'
 if x['nctId']=='NCT02119611':x['outcome_summary']='Current indication fields are not a verified Tourette cohort; excluded as in prior scan.'
write('search-log.json',r)
jsonl('primary-evidence.jsonl',[])
review=next(x for x in r['pubmed']['date_type_correction_screen'] if x['pmid']=='42888480')
jsonl('secondary-screening.jsonl',[{'date_checked':'2026-10-18','evidence_type':'secondary_narrative_review_screening_only','id':'pmid:42888480','title':review['title'],'doi':review['identifiers']['doi'],'source_urls':[review['source_url'],'https://doi.org/'+review['identifiers']['doi']],'publication_date':'2026-10-16','pubmed_history':review['history'],'crossref_metadata':supp['crossref'][0]['metadata'],'population_scope':'Children/adolescents; no new participant cohort and no severe-adult efficacy estimate.','study_type':'Clinically focused narrative synthesis, not primary research.','source_access':'PubMed abstract and metadata inspected transiently; Crossref metadata corroborated dates. No full-text assessment.','original_summary':'Proposes a differential-diagnosis framework for abdominal tic-like movements. No original controlled comparison or validated diagnostic accuracy is established by this review.','screening_decision':decisions['42888480'],'correction_retraction_check':'No linked PubMed notice; Crossref update-to empty at retrieval. This is limited metadata screening, not comprehensive clearance.','cohort_deduplication':'No new cohort; reviewed studies are not counted again as original data.','next_step':'Retain as secondary context only; reconsider if new primary validation or a material correction appears.'}])
prev={x['nctId']:x for x in old['registry_records']};records=[]
for x in r['registry_records']:
 n=x['nctId'];keys=['title','status','hasResults','conditions','design','eligibility'];changes={k:{'before':prev[n].get(k),'after':x.get(k)} for k in keys if prev[n].get(k)!=x.get(k)}
 records.append({'date_checked':'2026-10-18','evidence_type':'registry_recheck_not_new_evidence','id':'nct:'+n,'title':x['title'],'source_url':x['source_url'],'prior_snapshot':'updates/2026-10-17/search-log.json','compared_fields':keys,'changes':changes,'status':x['status'],'design':x['design'],'has_results':x['hasResults'],'decision':x['outcome_summary'],'new_result':False})
old_supp={x['id']:x for x in load('baseline/updates__2026-10-17__registry-supplement-selected.json')}
for x in supp['registry']:
 n=x['id'];keys=['status','design','hasResults'];prior=old_supp.get(n);changes={k:{'before':prior.get(k),'after':x.get(k)} for k in keys if prior.get(k)!=x.get(k)} if prior else None
 records.append({'date_checked':'2026-10-18','evidence_type':'registry_supplementary_recheck','id':'nct:'+n,'title':x['title'],'source_url':'https://clinicaltrials.gov/study/'+n,'prior_snapshot':'updates/2026-10-17/registry-supplement-selected.json' if prior else None,'compared_fields':keys if prior else [],'changes':changes,'status':x['status'],'design':x['design'],'has_results':x['hasResults'],'decision':('Existing expanded-access status/date/results fields unchanged; do not infer a new suspension or its cause.' if prior else 'Discovery mirror synchronization date was October 17, but official last posting is July 22. Excluded from new-window updates; no results.'),'new_result':False})
jsonl('registry-evidence.jsonl',records)
jsonl('integrity-recheck.jsonl',[{'date_checked':'2026-10-18','evidence_type':'historical_retraction_recheck','id':'retraction:pmid:42527169','affected_pmid':'39947542','notice_pmid':'42527169','affected_doi':'10.1016/j.ijbiomac.2025.140956','notice_doi':'10.1016/j.ijbiomac.2026.153656','source_urls':['https://pubmed.ncbi.nlm.nih.gov/39947542/','https://pubmed.ncbi.nlm.nih.gov/42527169/'],'electronic_notice_date':'2026-07-29','current_issue':'2026-10','new_linked_notice':False,'decision':'Preserve explicit exclusion of the retracted preclinical study from positive mechanism or efficacy evidence. No new reason or change in retraction status verified.','limitation':'Publisher retraction reason not re-investigated; no mechanism falsification inferred.'}])
summary={'date':'2026-10-18','core_started_utc':r['started_utc'],'core_completed_utc':r['completed_utc'],'supplement_completed_utc':load('isrctn-control.json')[-1]['completed_utc'],'inclusive_overlap':['2026-10-16','2026-10-18'],'primary_evidence_additions':0,'pubmed_unique':r['pubmed']['unique_records'],'pubmed_occurrences':r['pubmed']['id_occurrences'],'new_pubmed_ids':r['pubmed']['new_to_prior_scan_ids'],'secondary_reviews_newly_encountered':1,'preprint_doi_versions':sum(x['unique_doi_versions'] for x in r['preprints']),'preprint_lexical_matches':sum(len(x['matches']) for x in r['preprints']),'ctgov_unique_in_window':len(r['registry_records']),'ctgov_new_relevant_postings':0,'ctgov_new_results':0,'isrctn_window_total':int(supp['isrctn'][0]['root_attributes']['totalCount']),'isrctn_positive_control_total':int(load('isrctn-control.json')[0]['root_attributes']['totalCount']),'conclusion':'No new qualifying primary tic result or newly posted relevant registry result verified in bounded searches. A new narrative review is secondary evidence; known negative-feasibility and retraction records are retained.','coverage_limits':['Partial October 18 day and indexing lag.','PubMed is not all journals; no full-text review of every record.','Lexical screen on two preprint servers may miss synonym-only work or other servers.','CTgov and ISRCTN are not worldwide registry coverage.','WHO ICTRP landing page only, latest listed imports October 12; no query export. CTIS shell only.','No claim of a cure, absence of all relevant research, or a change in care.']}
write('summary.json',summary)
print(json.dumps(summary,indent=2))
